  (bank_id, otr_number, module, chapter, context, star, corrected, stem, options, justification, sources)
values
(1001, 24, 'MPR', 'Paraplégie', NULL, false, true, 'La paraplégie se caractérise par: La/Les RJ', '[{"l":"A","t":"Perte dela motricite volontaire.","c":true},{"l":"B","t":"Perte dela motricite involontaire.","c":false},{"l":"C","t":"Perte dela sensibilite","c":false},{"l":"D","t":"Un tonus normal.","c":true},{"l":"E","t":"S’accompagne des troubles vesicosphincteriens.","c":true}]'::jsonb, NULL, '["Auto-évaluation OTR 2014-2022"]'::jsonb),
(1002, 24, 'MPR', 'Paraplégie', NULL, false, true, 'Le tableau clinique d’une paraplégie est défini par: La/Les RJ', '[{"l":"A","t":"Un syndrome lesionnel.","c":true},{"l":"B","t":"Un syndromes ous-lésionnel.","c":true},{"l":"C","t":"Un syndromes upra-lésionnel.","c":false},{"l":"D","t":"Un syndrome pyramidal.","c":true},{"l":"E","t":"Un syndrome extrapyramidal","c":false}]'::jsonb, NULL, '["Auto-évaluation OTR 2014-2022"]'::jsonb),
(1003, 24, 'MPR', 'Paraplégie', NULL, false, true, 'La classification d’une paraplégie selon l’échelle de déficience ASIA comprend 5 stades: La RJ', '[{"l":"A","t":"Asia a:lésionsensitivomotriceincomplète.","c":false},{"l":"B","t":"Asia b:lesion motrice incomplete,sensitive incomplete.","c":false},{"l":"C","t":"Asia c:lesion motrice complete non fonctionnelle.","c":false},{"l":"D","t":"Asia d:lesion motrice complete fonctionnelle.","c":false},{"l":"E","t":"Asia e:Normale ou recuperation complete.","c":true}]'::jsonb, NULL, '["Auto-évaluation OTR 2014-2022"]'::jsonb),
(1004, 24, 'MPR', 'Paraplégie', NULL, false, true, 'La paraplégie est caractérisée par: La RJ', '[{"l":"A","t":"Uneabsencedetroublesvésico-sphinctériens.","c":false},{"l":"B","t":"Une origine traumatique dans100%des cas.","c":false},{"l":"C","t":"Un niveau neurologique qui correspond au premier metamere sain.","c":false},{"l":"D","t":"Un caractere toujours complet.","c":false},{"l":"E","t":"Un niveau lésionnel et une altération en sous lésionnel.","c":true}]'::jsonb, NULL, '["Auto-évaluation OTR 2014-2022"]'::jsonb),
(1005, 24, 'MPR', 'Paraplégie', NULL, false, true, 'La paraplégie est caractérisée par: La/Les RJ', '[{"l":"A","t":"Des troubles vesico-sphinctériens","c":true},{"l":"B","t":"Une origine traumatique dans100%des cas","c":false},{"l":"C","t":"Un niveau neurologique qui correspond en premier metamere sain","c":false},{"l":"D","t":"Un caractere toujours complet","c":false},{"l":"E","t":"Un niveau lésionnel est une altération en sous lésionnel","c":true}]'::jsonb, NULL, '["Auto-évaluation OTR 2014-2022"]'::jsonb),
(1006, 24, 'MPR', 'Paraplégie', NULL, false, true, 'Le niveau de la paraplégie:', '[{"l":"A","t":"Correspond toujours au niveau osseux en cas de fractures vertebrales","c":false},{"l":"B","t":"Correspond au dernier metamere sain","c":true},{"l":"C","t":"Est déterminé par un examen clinique des muscles clés,etdela sensibilite des dermatomes cles","c":true},{"l":"D","t":"Est determine par l’examen du tonus musculaire","c":false},{"l":"E","t":"Est absent dans les causes médicales de la paraplégie","c":false}]'::jsonb, NULL, '["Auto-évaluation OTR 2014-2022"]'::jsonb),
(1007, 29, 'MPR', 'Algoneurodystrophie', NULL, false, true, 'Dans le SDRC, la scintigraphie:', '[{"l":"A","t":"Est indispensable au diagnostic","c":false},{"l":"B","t":"Est specifique mais peu sensible","c":false},{"l":"C","t":"Est sensible mais non specifique","c":true},{"l":"D","t":"Montre une hypofixation","c":false},{"l":"E","t":"Montre une hyper fixation","c":true}]'::jsonb, NULL, '["Auto-évaluation OTR 2014-2022"]'::jsonb),
(1008, 24, 'MPR', 'Paraplégie', NULL, false, true, 'A propos des traumatismes vertébro-médullaires au niveau cervical. Cochez le seul énoncé qui est incorrect parmi ces affirmations.', '[{"l":"A","t":"Une tétraplégie complète n’a quasi aucune chance de récupérer après 48 heures","c":false},{"l":"B","t":"La présence d’un réflexe bulbo-caverneux témoigne de l’absence d’un choc spinal","c":true},{"l":"C","t":"La recherche d’une conservation de la sensibilité de la région péri-anale est un temps essentiel de l’examen clinique à l’entrée","c":false},{"l":"D","t":"Un tonus résiduel du sphincter anal signifie une atteinte incomplète de la moelle","c":false},{"l":"E","t":"Une tétraplégie C5-C6 ne nécessite pas une assistance ventilatoire","c":false}]'::jsonb, NULL, '["Banque de QCM OTR"]'::jsonb),
(1009, 2, 'MPR', 'Polyarthrite rhumatoïde', 'EPREUVE THEORIQUE SECTION «B» Examen 5eme année unité appareil locomoteur', false, false, 'Prices examens biologiques, lesquels sont spécifiques de rhumatoide?', '[{"l":"A","t":"AAN","c":false},{"l":"B","t":"FR","c":false},{"l":"C","t":"VS","c":false},{"l":"D","t":"CRP","c":false},{"l":"E","t":"ACPA","c":false}]'::jsonb, NULL, '["EMD section B promo 2019 (22/02/2024)"]'::jsonb),
(1010, 4, 'MPR', 'Situations d’handicap et concept de qualité de vie', 'EPREUVE THEORIQUE SECTION «B» Examen 5eme année unité appareil locomoteur', false, false, 'Parmi les propositions suivantes concemant la classification intemationale du fonctionnement CIF lesquelles sont vraies?', '[{"l":"A","t":"Elle tent compte des facteurs environnementaux","c":false},{"l":"B","t":"Elle est caractérisée par la déficience. Fincapacité et le désavantage,","c":false},{"l":"C","t":"Elle est caractérisée par la fonction organique et les structures anatomiques","c":false},{"l":"D","t":"Elle distingue quatre niveaux d’expression de la maladie","c":false},{"l":"E","t":"Elle ne bent pas compte des facteurs environnementaux","c":false}]'::jsonb, NULL, '["EMD section B promo 2019 (22/02/2024)"]'::jsonb),
(1011, 7, 'MPR', 'Escarres et décubitus', NULL, true, true, 'Quels sont les objectifs de la rééducation à la phase aiguë du traumatisme: (les réponses justes)', '[{"l":"A","t":"Récupérer les amplitudes articulaires et une force musculaire maximale.","c":false},{"l":"B","t":"Prévenir les complications liées au décubitus et à la douleur.","c":true},{"l":"C","t":"Prévenir les attitudes vicieuses.","c":true},{"l":"D","t":"Prévenir la fonte musculaire et l’enraidissement articulaire.","c":true},{"l":"E","t":"Rééducation proprioceptive.","c":false}]'::jsonb, NULL, '["Auto-évaluation OTR 2014-2021"]'::jsonb),
(1012, 7, 'MPR', 'Escarres et décubitus', NULL, true, true, 'Concernant des complications du décubitus: LA OU LES RJ', '[{"l":"A","t":"L’immobilisation augmente la stase l’infection et encombrement","c":true},{"l":"B","t":"L‘immobilisation progressive provoque hypotension orthostatique","c":false},{"l":"C","t":"****** développer une escarre est favorisé par existence incontinence urinaire ou anale","c":true},{"l":"D","t":"****** est un moyen de prévention des accidents thromboembolique","c":false},{"l":"E","t":"****** une escarre infectée se fait par une antibiothérapie locale","c":false}]'::jsonb, NULL, '["Auto-évaluation OTR 2014-2021"]'::jsonb),
(1013, 7, 'MPR', 'Escarres et décubitus', NULL, false, true, 'Parmi les affirmations suivantes concernant le risque de complications cutanées liées à l’hypo mobilité, laquelle (lesquelles) est (sont) exacte(s) ?', '[{"l":"A","t":"Le choix correct du support sur lequel repose le patient permet d’alléger la surveillance cutanée chez ce patient","c":false},{"l":"B","t":"L’hypovolémie et l’anémie favorisent la survenue des complications cutanées.","c":false},{"l":"C","t":"La prévention des complications cutanées liées à l’hypo mobilité repose uniquement sur l’équipe thérapeutique, sans faire participer activement le patient, même s’il est conscient et bien orienté.","c":false},{"l":"D","t":"L’existence de troubles neuro-orthopédiques (tels qu’un flessum de genou ou de hanche) ne modifie pas le risque cutané chez un patient nécessitant un maintien en décubitus","c":true},{"l":"E","t":"Les déplacements d’un patient alité en vue d’examens complémentaires longs constituent des facteurs de risque surajoutés de complications cutanées","c":true}]'::jsonb, NULL, '["Auto-évaluation OTR 2014-2021"]'::jsonb),
(1014, 7, 'MPR', 'Escarres et décubitus', NULL, false, true, 'Parmi les affirmations suivantes concernant les escarres constituées chez un sujet immobilisé, et leurs complications, laquelle (lesquelles) est (sont) exacte(s) ?', '[{"l":"A","t":"L’apparition d’escarres nécessite une suppression de l’appui de cette zone et l’adaptation de la correction des facteurs de risque.","c":true},{"l":"B","t":"Sur une lésion ouverte, les soins locaux comprennent l’application régulière d’antiseptiques ou, au besoin, d’antibiotiques locaux","c":false},{"l":"C","t":"La perception d’un contact osseux au fond d’une escarre de stade 4 doit faire rechercher une ostéite.","c":true},{"l":"D","t":"La réalisation d’une fistulographie est licite lorsqu’on suspecte une extension sous-cutanée d’une escarre avec ouverture cutanée de petite taille","c":true},{"l":"E","t":"La chirurgie de l’escarre se limite à des interventions de couverture une fois que le bourgeonnement a comblé la perte de substance profonde","c":false}]'::jsonb, NULL, '["Auto-évaluation OTR 2014-2021"]'::jsonb),
(1015, 7, 'MPR', 'Escarres et décubitus', NULL, false, true, 'L’escarre est une pathologie multifactorielle, parmi les facteurs extrinsèques: (Cocher la ou les Réponses justes)', '[{"l":"A","t":"L’état général du patient","c":false},{"l":"B","t":"L’augmentation de friction–cisaillement de la zone concernée","c":true},{"l":"C","t":"L’état d’hydratation et de la nutrition du patient","c":false},{"l":"D","t":"L’état de conscience du patient","c":false},{"l":"E","t":"L’augmentation de la pression au niveau de la zone concernée entre deux plans durs","c":true}]'::jsonb, NULL, '["Auto-évaluation OTR 2014-2021"]'::jsonb),
(1016, 7, 'MPR', 'Escarres et décubitus', NULL, false, true, 'Concernant les complications de décubitus: (Cocher la ou les Réponses justes)', '[{"l":"A","t":"L’immobilisation augmente la résorption osseuse","c":true},{"l":"B","t":"La verticalisation progressive provoque l’hypotension orthostatique","c":false},{"l":"C","t":"Le risque de développer une escarre est favorisé par l’existence de troubles sensitifs","c":true},{"l":"D","t":"Il n’existe pas un risque d’escarre au niveau des omoplates en décubitus dorsal","c":false},{"l":"E","t":"Les bas de contention est un moyen de prévention des accidents thromboemboliques","c":true}]'::jsonb, NULL, '["Auto-évaluation OTR 2014-2021"]'::jsonb),
(1017, 7, 'MPR', 'Escarres et décubitus', NULL, false, true, 'Une escarre sacrée se présente comme une phlyctène de 3 cm de diamètre à contenu séreux. Quel est le stade de cette escarre ?', '[{"l":"A","t":"Stade 0","c":false},{"l":"B","t":"Stade 1","c":false},{"l":"C","t":"Stade 2","c":true},{"l":"D","t":"Stade 3","c":false},{"l":"E","t":"Aucun de ces stades","c":false}]'::jsonb, NULL, '["Auto-évaluation OTR 2014-2021","Auto-évaluation OTR 2014-2022"]'::jsonb),
(1018, 7, 'MPR', 'Escarres et décubitus', NULL, true, true, 'Les situations nécessitants un décubitus prolongé: (la ou les réponses fausses):', '[{"l":"A","t":"Hémiplégie ancienne (séquellaire).","c":false},{"l":"B","t":"Fractures du membre inferieur ostéosynthèse.","c":false},{"l":"C","t":"Coma et troubles de la vigilance.","c":true},{"l":"D","t":"Décompensation cardiaque.","c":true},{"l":"E","t":"Pathologies rhumatismales dégénératives.","c":false}]'::jsonb, NULL, '["Auto-évaluation OTR 2014-2021"]'::jsonb),
(1019, 7, 'MPR', 'Escarres et décubitus', NULL, true, true, 'Les facteurs qui favorisent l’installation des escarres: (la ou les réponses justes)', '[{"l":"A","t":"Pression artériolaire supérieure à la pression exercée.","c":false},{"l":"B","t":"Dégradation de l’état nutritionnel du patient.","c":true},{"l":"C","t":"Incontinence fécale et urinaire,","c":true},{"l":"D","t":"Troubles métaboliques associés.","c":true},{"l":"E","t":"Toutes les réponses sont justes.","c":false}]'::jsonb, NULL, '["Auto-évaluation OTR 2014-2021"]'::jsonb),
(1020, 7, 'MPR', 'Escarres et décubitus', NULL, false, true, 'Concernant les escarres: RF(s)', '[{"l":"A","t":"sont provoqués par une compression des parties molles sur les reliefs osseux","c":false},{"l":"B","t":"doivent être prévenues par les retournements, l’utilisation d’un support adapté et la prévention de la macération","c":false},{"l":"C","t":"selon la profondeur de lésions, on distingue deux stades: stade 1: érythème; stade 2: perte de substance profonde, touchant les trois couches de la peau","c":true},{"l":"D","t":"leur localisation correspond aux zones d’appui sur la position du patient","c":false},{"l":"E","t":"quel que soit leur stade, les lésions sont réversibles avec la prévention et les soins","c":false}]'::jsonb, NULL, '["Auto-évaluation OTR 2014-2021"]'::jsonb),
(1021, 7, 'MPR', 'Escarres et décubitus', NULL, false, true, 'Parmi les propositions suivantes relatives aux escarres, la (les) quelle(s) est (sont)exacte(s)', '[{"l":"A","t":"l’escarre est une nécrose cutanée","c":true},{"l":"B","t":"l’escarre de décubitus est due à une ischémie induite par la pression d’appui","c":true},{"l":"C","t":"un des premiers signes cliniques avant l’apparition d’une escarre est la rougeur","c":true},{"l":"D","t":"le meilleur moyen de lutter contre l’apparition d’escarre et de mobiliser les patients toutes les six heures","c":false},{"l":"E","t":"chez le paraplégique, l’escarre la plus fréquente est l’escarre sacrée","c":true}]'::jsonb, NULL, '["Auto-évaluation OTR 2014-2021"]'::jsonb),
(1022, 7, 'MPR', 'Escarres et décubitus', NULL, true, true, 'Quelles sont les propositions exactes concernant les complications de l’immobilité et du décubitus dans le cas de ce patient ?', '[{"l":"A","t":"Les rétractions musculo-tendineuses ne surviennent pas chez un patient dans le coma","c":false},{"l":"B","t":"Les verticalisations précoces sont utiles.","c":true},{"l":"C","t":"Il existe un risque accru de lithiase urinaire.","c":false},{"l":"D","t":"Une installation correcte au lit peut prévenir certaines complications orthopédiques.","c":true},{"l":"E","t":"Les escarres ne surviennent pas avant la fin du deuxième mois d’alitement","c":false}]'::jsonb, NULL, '["Auto-évaluation OTR 2014-2021"]'::jsonb),
(1023, 7, 'MPR', 'Escarres et décubitus', 'Mr B. Mohamed âgé de 55 ans, sans antécédents particuliers, se présente a 2h00 du matin aux urgences médicales pour une douleur vive et insomniante de la cheville gauche sans notion de traumatisme. L’interrogatoire retrouve la notion d’un excés alimentaire la veille lors d’un mariage d’un proche. L’examen clinique retrouve: un patient agité, T: 38 °C, TA 13/08 cm hg, poids: 94kg pour une taille de 1m 78. L’examen articulaire: la cheville gauche est rouge, chaude et nettement augmentée de volume en comparaison avec la cheville droite, sa mobilisation est très douloureuse voire impossible.', false, true, 'Quelles mesures thérapeutiques sont nécessaire pour prévenir les complications de décubitus chez un paraplégique ? La RF', '[{"l":"A","t":"Heparine de bas poids moleculaire","c":false},{"l":"B","t":"Bas de contention","c":false},{"l":"C","t":"Decubitus strict sur plan dur","c":true},{"l":"D","t":"Bonne hydratation et alimentation en position assiseousemi-assise","c":false},{"l":"E","t":"Mobilisations precoces","c":false}]'::jsonb, NULL, '["Auto-évaluation OTR 2014-2022","EMD OTR section A"]'::jsonb),
(1024, 7, 'MPR', 'Escarres et décubitus', 'Mr B. Mohamed âgé de 55 ans, sans antécédents particuliers, se présente a 2h00 du matin aux urgences médicales pour une douleur vive et insomniante de la cheville gauche sans notion de traumatisme. L’interrogatoire retrouve la notion d’un excés alimentaire la veille lors d’un mariage d’un proche. L’examen clinique retrouve: un patient agité, T: 38 °C, TA 13/08 cm hg, poids: 94kg pour une taille de 1m 78. L’examen articulaire: la cheville gauche est rouge, chaude et nettement augmentée de volume en comparaison avec la cheville droite, sa mobilisation est très douloureuse voire impossible.', false, true, 'Concernant les complications de décubitus:', '[{"l":"A","t":"L’escarre et une complication tardive","c":false},{"l":"B","t":"Le traitement d’une escarre infectee se fait par une antibiotherapie locale.","c":false},{"l":"C","t":"La thrombose veineuse profonde peut être asymptomatique et être découverte devant un tableaud’emboliepulmonaire,","c":true},{"l":"D","t":"L’immobilisation augmente la stase bronchique, l’encombrementetl’infection","c":true},{"l":"E","t":"La prévention des infections urinaires se fait par le maintien d’un drainage continu(sondage intermittent)","c":true}]'::jsonb, NULL, '["Auto-évaluation OTR 2014-2022"]'::jsonb),
(1025, 7, 'MPR', 'Escarres et décubitus', 'Mr B. Mohamed âgé de 55 ans, sans antécédents particuliers, se présente a 2h00 du matin aux urgences médicales pour une douleur vive et insomniante de la cheville gauche sans notion de traumatisme. L’interrogatoire retrouve la notion d’un excés alimentaire la veille lors d’un mariage d’un proche. L’examen clinique retrouve: un patient agité, T: 38 °C, TA 13/08 cm hg, poids: 94kg pour une taille de 1m 78. L’examen articulaire: la cheville gauche est rouge, chaude et nettement augmentée de volume en comparaison avec la cheville droite, sa mobilisation est très douloureuse voire impossible.', false, true, 'Concernant des complications du décubitus:', '[{"l":"A","t":"L’immobilisation augmente la stase bronchique, encombrementetl’infection","c":true},{"l":"B","t":"La verticalisation progressive provoque hypotension orthostatique","c":false},{"l":"C","t":"Le risque développer une escarre est favorisé par existence incontinence urinaire ou anale","c":true},{"l":"D","t":"Les bas de contention est un moyen de prévention des accidents thromboembolique","c":true},{"l":"E","t":"Le traitement d’une escarre infectee se fait par une antibiotherapie locale","c":false}]'::jsonb, NULL, '["Auto-évaluation OTR 2014-2022"]'::jsonb),
