(1058, 29, 'MPR', 'Algoneurodystrophie', 'Un homme de 40 ans a eu un accident de circulation. Cet accident a conduit à devoir réaliser une amputation de membre inférieur à la jonction du tiers moyen-tiers supérieur de la jambe gauche. Dix jours après l’intervention le patient a été admis dans un service de rééducation', false, true, 'L’immobilité entraîne: La/Les RJ', '[{"l":"A","t":"Une demineralisation osseuse.","c":true},{"l":"B","t":"Unenraidissementarticulaire.","c":true},{"l":"C","t":"Des paraosteo arthropathies neurogenes(PAON).","c":false},{"l":"D","t":"Une algoneurodystrophie.","c":false},{"l":"E","t":"Une amyotrophie.","c":true}]'::jsonb, NULL, '["Auto-évaluation OTR 2014-2022","EMD OTR section A"]'::jsonb),
(1059, 29, 'MPR', 'Algoneurodystrophie', 'Un homme de 40 ans a eu un accident de circulation. Cet accident a conduit à devoir réaliser une amputation de membre inférieur à la jonction du tiers moyen-tiers supérieur de la jambe gauche. Dix jours après l’intervention le patient a été admis dans un service de rééducation', false, true, 'Le ou les signes faisant craindre l’apparition d’une algodystrophie au niveau de la main est ou sont:', '[{"l":"A","t":"Douleur","c":false},{"l":"B","t":"œdème","c":false},{"l":"C","t":"Perte de sensibilité superficielle","c":false},{"l":"D","t":"Abolition des pouls","c":false},{"l":"E","t":"Hypersudation","c":true}]'::jsonb, NULL, '["Banque de QCM OTR"]'::jsonb),
(1060, 29, 'MPR', 'Algoneurodystrophie', 'EPREUVE THEORIQUE SECTION «B» Examen 5eme année unité appareil locomoteur', false, false, 'Concernant la clinique d’un syndrome douloureux régional complexe (Algodystrophie)', '[{"l":"A","t":"Il associe classiquement une phase froide puis chaude","c":false},{"l":"B","t":"Il associe classiquement une phase chaude puis tiède puis froide","c":false},{"l":"C","t":"La phase chaude s’étale jusqu’à la guérison qui peut être longue","c":false},{"l":"D","t":"L’évolution peut être prolongée 12 à 24 mois","c":false},{"l":"E","t":"La phase froide se manifeste par des troubles trophiques et des rétractions","c":false}]'::jsonb, NULL, '["EMD section B promo 2019 (22/02/2024)"]'::jsonb),
(1061, 29, 'MPR', 'Algoneurodystrophie', 'EPREUVE THEORIQUE SECTION «B» Examen 5eme année unité appareil locomoteur', false, false, 'Concernant le traitement du syndrome douloureux régional complexe', '[{"l":"A","t":"Aucun traitement n’a TAMM","c":false},{"l":"B","t":"La calcitonine est efficace","c":false},{"l":"C","t":"Le Rituximab a prouvé son efficacité","c":false},{"l":"D","t":"La kinésithérapie lutte contre l’enraidissement à la phase froide","c":false},{"l":"E","t":"La kinésithérapie doit être progressive et indolore lors de la phase chaude","c":false}]'::jsonb, NULL, '["EMD section B promo 2019 (22/02/2024)"]'::jsonb),
(1062, 30, 'Orthopédie', 'Tumeurs osseuses (bénignes et malignes)', 'EPREUVE THEORIQUE SECTION «B» Examen 5eme année unité appareil locomoteur', false, false, 'Parmi les propositions ci-dessous, quelles sont les tumeurs considérées comme malignes: (Cochez les réponses justes)', '[{"l":"A","t":"Le chondroblastome","c":false},{"l":"B","t":"Le fibrosarcome","c":false},{"l":"C","t":"La tumeur d’Ewing","c":false},{"l":"D","t":"Ostéome ostéoide","c":false},{"l":"E","t":"Ostéoblastome Q 28. Quels signes radiographiques parmi les suivants pouvez-vous retrouver dans ?A. Une déminéralisation osseuse mouchetée","c":false},{"l":"B","t":"Une érosion du rebord antérieur et antérolatéral des corps vertébraux","c":false},{"l":"C","t":"Une spondylodiscite d’Andersson","c":false},{"l":"D","t":"Un pincement coxofémoral","c":false},{"l":"E","t":"Une érosion calcanéenne avec ébauche d’apposition périostée Q 29. Le tableau clinique du SDRC 1 (Algodystrophie) se caractérise par:","c":false},{"l":"A","t":"Une douleur régionale continue, spontanée ou provoquée, de faible intensité et de courte durée","c":false},{"l":"B","t":"Une douleur correspondant à un territoire nerveux périphérique radiculaire","c":false},{"l":"C","t":"Peut être associé à des signes cliniques moteurs, sensitifs, sudomoteurs, vasomoteurs et trophiques","c":false},{"l":"D","t":"Une douleur qui paralt disproportionnée par rapport à l’évolution attendue de l’événement déclenchant","c":false},{"l":"E","t":"Une arthrite qui peut durer quelques semaines à 6 mois","c":false}]'::jsonb, NULL, '["Rattrapage OTR promo 2019"]'::jsonb),
(1063, 21, 'Rhumatologie', 'Arthrite septique', 'EPREUVE THEORIQUE SECTION «B» Examen 5eme année unité appareil locomoteur', false, false, 'Concernant la clinique d’un syndrome douloureux régional complexe (Algodystrophie)', '[{"l":"A","t":"Il associe classiquement une phase froide puis chaude","c":false},{"l":"B","t":"Il associe classiquement une phase chaude puis tiède puis froide","c":false},{"l":"C","t":"La phase chaude s’étale jusqu’à la guérison qui peut être longue","c":false},{"l":"D","t":"L’évolution peut être prolongée 12 à 24 mois","c":false},{"l":"E","t":"La phase froide se manifeste par des troubles trophiques et des rétractions Q 31. Au cours d’une arthrite goutteuse aiguë, l’exploration biologique peut retrouver:","c":false},{"l":"A","t":"Une uricémie normale","c":false},{"l":"B","t":"Un syndrome inflammatoire biologique","c":false},{"l":"C","t":"Des hémocultures positives","c":false},{"l":"D","t":"Un liquide synovial très inflammatoire sans germes à l’examen direct ni à la culture","c":false},{"l":"E","t":"La présence obligatoire de cristaux de pyrophosphate de calcium Q 32. La goutte primaire idiopathique est caractérisée par:","c":false},{"l":"A","t":"Son association fréquente aux éléments du syndrome métabolique","c":false},{"l":"B","t":"Sa relation avec des déficits enzymatiques fréquents","c":false},{"l":"C","t":"Une prédominance de l’atteinte féminine","c":false},{"l":"D","t":"Des antécédents de goutte familiale dans 30-40% des cas","c":false},{"l":"E","t":"Une évolution obligatoirement bénigne Q 33. Parmi les facteurs suivants; lesquels peuvent être incriminės dans l’apparition de l’ostéoporose:","c":false},{"l":"A","t":"L’obésité.","c":false},{"l":"B","t":"L’hypothyroïdie.","c":false},{"l":"C","t":"L’hysterectomie.","c":false},{"l":"D","t":"L’intoxication tabagique","c":false},{"l":"E","t":"La ménopause précoce. Q 34. L’atteinte articulaire de la polyarthrite rhumatoïde débutante est souvent:","c":false},{"l":"A","t":"Distale","c":false},{"l":"B","t":"Fugace","c":false},{"l":"C","t":"Migratrice","c":false},{"l":"D","t":"Symétrique","c":false},{"l":"E","t":"Déformante Q 35. Le DAS 28 comprend:","c":false},{"l":"A","t":"Le nombre d’articulation douloureuse","c":false},{"l":"B","t":"Le nombre d’articulations gonflées","c":false},{"l":"C","t":"L’EVA globale patient","c":false},{"l":"D","t":"Le taux de CRP","c":false},{"l":"E","t":"Le taux de FR Q 36. Au cours d’une arthrite septique à pyogènes quel(s) est/ sont les éléments en faveur d’une disséminatin par voie hématogène ?","c":false},{"l":"A","t":"Existence d’un foyer infectieux à distance de l’articulation","c":false},{"l":"B","t":"Un terrain d’immunodépression","c":false},{"l":"C","t":"Réalisation d’un geste intra- articulaire","c":false},{"l":"D","t":"Existence d’une lésion cutanée en regard de l’articulation","c":false},{"l":"E","t":"Traumatisme articulaire Q 37. Le diagnostic de certitude d’une arthrite septique à germe banal repose sur la mise en évidence du germe dans:","c":false},{"l":"A","t":"Le liquide céphalo-rachidien","c":false},{"l":"B","t":"Le liquide pleural","c":false},{"l":"C","t":"Le liquide synovial","c":false},{"l":"D","t":"La culture d’une biopsie synoviale","c":false},{"l":"E","t":"Les hémocultures Q 38. Au cours d’une coxarthrose primitive, on peut retrouver:","c":false},{"l":"A","t":"Une douleur mécanique projetée au genou homolatéral","c":false},{"l":"B","t":"Une démarche dandinante","c":false},{"l":"C","t":"Une limitation précoce de la flexion de hanche","c":false},{"l":"D","t":"Une réduction progressive du périmètre de marche","c":false},{"l":"E","t":"Une amyotrophie du jambier antérieur Q 39. Une sciatique commune par hernie discale se manifeste par:","c":false},{"l":"A","t":"Début brutal après effort","c":false},{"l":"B","t":"Douleur irradiant au creux inguinal","c":false},{"l":"C","t":"Douleur de type mécanique","c":false},{"l":"D","t":"Impulsivité aux éternuements","c":false},{"l":"E","t":"Dérouillage matinal supérieur à une heure Q 40. En cas de conflit disco-radiculaire type S1, on peut retrouver:","c":false},{"l":"A","t":"Douleur de la fesse irradiant à la face antéro-exteme de la cuisse et du mollet","c":false},{"l":"B","t":"Lasègue à 10”","c":false},{"l":"C","t":"Attitude antalgique en inflexion latérale","c":false},{"l":"D","t":"Altération de l’état général avec fièvre et anorexie","c":false},{"l":"E","t":"Douleur de la fesse irradiant à la face postérieure de la cuisse et du mollet Q 41. Le Palm up test explore:","c":false},{"l":"A","t":"Muscle supra-épineux","c":false},{"l":"B","t":"Muscle subscapulaire","c":false},{"l":"C","t":"Chef long du muscle biceps brachial","c":false},{"l":"D","t":"Muscle infra-épineux","c":false},{"l":"E","t":"Muscle petit rond","c":false}]'::jsonb, NULL, '["Rattrapage OTR promo 2019"]'::jsonb),
