(1133, 18, 'Autre', 'Non classé', 'Un homme de 40 ans a eu un accident de circulation. Cet accident a conduit à devoir réaliser une amputation de membre inférieur à la jonction du tiers moyen-tiers supérieur de la jambe gauche. Dix jours après l’intervention le patient a été admis dans un service de rééducation', false, true, 'L’allodynie est: La/Les RJ', '[{"l":"A","t":"Une augmentation ou exagération des divers modesdesensibilité.","c":false},{"l":"B","t":"Une sensation douloureuse causée par une stimulation non nociceptive","c":true},{"l":"C","t":"Une sensation désagréable par effleurage de la peau","c":false},{"l":"D","t":"Tout trouble de la sensibilité, notamment de la sensibilite tactile.","c":false},{"l":"E","t":"Une sensation de brûlure lancinante avec hyperesthesie cutanee et troubles vasomoteurs","c":false}]'::jsonb, NULL, '["Auto-évaluation OTR 2014-2022"]'::jsonb),
(1134, 39, 'Autre', 'Non classé', 'Mr B. Mohamed âgé de 55 ans, sans antécédents particuliers, se présente a 2h00 du matin aux urgences médicales pour une douleur vive et insomniante de la cheville gauche sans notion de traumatisme. L’interrogatoire retrouve la notion d’un excés alimentaire la veille lors d’un mariage d’un proche. L’examen clinique retrouve: un patient agité, T: 38 °C, TA 13/08 cm hg, poids: 94kg pour une taille de 1m 78. L’examen articulaire: la cheville gauche est rouge, chaude et nettement augmentée de volume en comparaison avec la cheville droite, sa mobilisation est très douloureuse voire impossible.', false, true, 'Une orthèse: La/Les RJ', '[{"l":"A","t":"Peut se porter aux membres inférieurs, aux membres superieurs etau tronc.","c":true},{"l":"B","t":"Peut etre fabriquee par une rgo the ra peut e.","c":true},{"l":"C","t":"Remplace un segment deme mbre.","c":false},{"l":"D","t":"Peut pallier une deficience.","c":true},{"l":"E","t":"Ne peut pas etre portee par des enfants.","c":false}]'::jsonb, NULL, '["Auto-évaluation OTR 2014-2022","EMD OTR section A"]'::jsonb),
(1135, 39, 'Autre', 'Non classé', 'Mr B. Mohamed âgé de 55 ans, sans antécédents particuliers, se présente a 2h00 du matin aux urgences médicales pour une douleur vive et insomniante de la cheville gauche sans notion de traumatisme. L’interrogatoire retrouve la notion d’un excés alimentaire la veille lors d’un mariage d’un proche. L’examen clinique retrouve: un patient agité, T: 38 °C, TA 13/08 cm hg, poids: 94kg pour une taille de 1m 78. L’examen articulaire: la cheville gauche est rouge, chaude et nettement augmentée de volume en comparaison avec la cheville droite, sa mobilisation est très douloureuse voire impossible.', false, true, 'Quel est le tendon exploré par la manouvre du Luft off test de Gerber ?', '[{"l":"A","t":"Les upra-spinatus","c":false},{"l":"B","t":"L’infra-spinatus","c":false},{"l":"C","t":"Le long biceps","c":false},{"l":"D","t":"Les ous-scapulaire","c":true},{"l":"E","t":"Le petit rond","c":false}]'::jsonb, NULL, '["Auto-évaluation OTR 2014-2022"]'::jsonb),
